def sql_in(col, vals): return f'{col} in ({",".join(map(repr, vals))})'  # SQL IN clause; callers guard against empty vals

_FTS_TOKENIZE = 'porter simplify casefold 1 sanskrit unicodewords'

class StoreMismatch(ValueError):
    'Raised when a store is reopened with a different encoder or tokenizer than the one that created it.'

def _tokenizers_ok(conn, chain:str=None) -> bool:
    'Whether the tokenizer chain `chain` can be built on this connection.'
    parts = (chain or _FTS_TOKENIZE).split()
    try:
        conn.fts5_tokenizer(parts[0], parts[1:])
        return True
    except Exception: return False

def content_id(content): return hash_record({'content': content}) if content else None

def embed_chunk(chunk,      # iterable of dicts with a 'content' key
                emb_fn,     # callable: list[str] -> list of vectors (np arrays)
                **kw):
    'Drop chunks with blank content and give each remaining chunk an `embedding` from `emb_fn`, as bytes.'
    c = L(chunk).filter(lambda b: b.get('content') and b['content'].strip())
    if not c: return []
    for e,b in zip(emb_fn(list(c.itemgot('content')), **kw), c): b['embedding'] = np.asarray(e).tobytes()
    return list(c)

@contextmanager
def busy_window(busy_ms=BUSY_TIMEOUT_MS):
    'Deprecated no-op. `busy_ms` is ignored. Set `database(busy_timeout=...)` instead.'
    yield

class _WriteConnection(apsw.Connection):
    def __init__(self, path, timeout):
        self._open_timeout = timeout
        super().__init__(path)
        self._open_timeout = None
        self.set_busy_timeout(timeout)

    def set_busy_timeout(self, timeout):
        # Bestpractice sets the timeout before its WAL and optimize pragmas.
        super().set_busy_timeout(timeout if self._open_timeout is None else self._open_timeout)

_conn_locks, _load_locks, _conn_locks_guard = weakref.WeakKeyDictionary(), weakref.WeakKeyDictionary(), threading.Lock()
def _lock_for(locks, c):
    with _conn_locks_guard:
        if (lk := locks.get(c)) is None: lk = locks[c] = threading.RLock()
    return lk

def db_lock(db):
    'The re-entrant lock litesearch holds while it works on `db`\'s connection.'
    return db.conn.lock if isinstance(db.conn, Conn) else _lock_for(_conn_locks, db.conn)

def _load_lock(db):
    "The lock `get_index` and `usearch_sql` load under: a shared `Conn`'s own, which its statements take anyway, else one no `db_lock` holder waits on."
    return db.conn.lock if isinstance(db.conn, Conn) else _lock_for(_load_locks, db.conn)

@contextmanager
def write_txn(db):
    'A write transaction started with `BEGIN IMMEDIATE`; inside another one, it joins the open transaction.'
    c = db.conn
    with db_lock(db):
        if c.in_transaction: yield; return
        c.execute('BEGIN IMMEDIATE')
        try: yield
        except Exception: c.execute('ROLLBACK'); raise
        else: c.execute('COMMIT')

def _checkpoint(db):
    'Truncate the WAL with a short lock wait. Skip open transactions and busy checkpoints.'
    with db_lock(db):
        c = db.conn
        if c.in_transaction: return
        timeout = c.pragma('busy_timeout')
        try:
            c.set_busy_timeout(WAL_CHECKPOINT_MS)
            c.wal_checkpoint('main', apsw.SQLITE_CHECKPOINT_TRUNCATE)
        except (apsw.BusyError, apsw.LockedError): pass
        finally: c.set_busy_timeout(timeout)

def process_content(store,          # target Table (hash-id store)
                    content,        # iterable of chunk dicts
                    embed=True,     # embed content before upsert
                    emb_fn=None,    # embedder, required when embed=True
                    hash_id_columns=('content',),  # columns the row id is hashed over; add 'node_id' to keep identical text in different sections distinct
                    parallel=False, # deprecated and ignored
                    chunk=1_000,    # rows per transaction
                    **kw):          # forwarded to emb_fn
    "Upsert content-hash chunks in batches. Embed when requested. `parallel` is deprecated and ignored."
    content = list(content or [])
    if embed:
        assert emb_fn, 'emb_fn is required when embed=True'
        content = embed_chunk(content, emb_fn, **kw)
    if not content: return
    hc = list(hash_id_columns)
    for r in content:
        if not r.get('id'): r['id'] = hash_record(r, hc)
    upsert_all(store, content, 'id', chunk)
    return store


