def upsert_all(tbl,            # target Table, with `pk` declared as its primary key
               rows,           # dicts of scalars, upserted on `pk`
               pk,             # primary-key column name or tuple of them
               chunk=1000):    # rows per write transaction
    'Upsert rows in committed batches. Earlier batches remain committed if a later batch fails.'
    from apswutils.db import jsonify_if_needed as _j
    rows = list(rows)
    if not rows: return 0
    pks = (pk,) if isinstance(pk, str) else tuple(pk)
    cols = list(dict.fromkeys(k for r in rows for k in r))
    sets = [c for c in cols if c not in set(pks)]
    do = ('update set ' + ', '.join(f'[{c}]=excluded.[{c}]' for c in sets)) if sets else 'nothing'
    sql = (f'insert into [{tbl.name}] ({", ".join(f"[{c}]" for c in cols)}) '
           f'values ({", ".join("?" * len(cols))}) '
           f'on conflict ({", ".join(f"[{c}]" for c in pks)}) do {do}')
    for b in chunked(rows, chunk):
        with write_txn(tbl.db):
            tbl.db.conn.cursor().executemany(sql, [[_j(r.get(c)) for c in cols] for r in b])
    _checkpoint(tbl.db)
    return len(rows)

