def rowid_sel(): return 'rowid as rowid'
@patch
def ann_search(self:Table,          # store table (must be ANN-registered)
               emb:bytes,           # query embedding
               columns:list=None,   # columns to return (rowid always included)
               limit:int=50,        # max results
               where:str=None,        # additional where clause
               where_args:dict=None,  # args for where clause
               dtype=np.float16):      # embedding dtype
    'Approximate vector search through the store\'s HNSW index, nearest rows first, each with its distance in `_dist`.'
    m = self.db._ann_meta(self.name)
    if not (m and m['ndim']): return []
    idx = self.db.get_index(self.name)
    if not idx.size: return []
    res = idx.search(np.frombuffer(emb, dtype=dtype), count=limit*2)
    keys = np.atleast_1d(res.keys).tolist()   # -> python ints (L() would wrap the whole ndarray)
    if not keys: return []
    dist, ord = dict(zip(keys, np.atleast_1d(res.distances).tolist())), dict(L(keys).renumerate())
    cols = [c for c in (columns or []) if c != 'rowid']
    sel = ','.join(cols + [rowid_sel()]) if cols else '*, %s'%rowid_sel()
    wh = f'where {sql_in("rowid", keys)}' + (f' AND {where}' if where else '')
    rows = self.db.q(f'select {sel} from [{self.name}] {wh}', where_args or None)
    for r in rows: r['_dist'] = dist.get(r['rowid'])
    return sorted(rows, key=lambda r: ord.get(r['rowid'],1e10))[:limit]

@patch
def _idx_remove(self:Table, idx, keys):
    'Remove those of `keys` that the index holds, since usearch\'s remove does not ignore absent keys.'
    if (present := [k for k in keys if idx.contains(k)]): idx.remove(np.array(present, dtype=np.int64))

@patch
def _sync_index(self:Table, add_ids, rm_rowids, dtype=np.float16, save=True):
    'Add the rows with ids `add_ids` to the HNSW index and remove rowids `rm_rowids`, recording the vector length on first use.'
    with db_lock(self.db):
        m = self.db._ann_meta(self.name)
        if rm_rowids and m['ndim']: self._idx_remove(self.db.get_index(self.name), rm_rowids)
        kw = dict(select=f'{rowid_sel()}, embedding', where=sql_in('id', add_ids))
        rows = L(self(**kw)).filter(lambda r: r['embedding']) if add_ids else L()
        if rows:
            if (new := not m['ndim']):
                m['ndim'] = len(np.frombuffer(rows[0]['embedding'], dtype=dtype))
                self.db.t.usearch_indices.update(dict(name=self.name, ndim=m['ndim']))
            idx = self.db.get_index(self.name, load=not new)
            keys = rows.itemgot('rowid')
            self._idx_remove(idx, keys)
            idx.add(np.array(keys, dtype=np.int64), np.stack([np.frombuffer(b, dtype=dtype) for b in rows.itemgot('embedding')]))
        if save: self.db._save_index(self.name)

@patch
def _refresh(self:Table, ids, rows, chunk=1_000):
    'Rewrite the columns other than `id`, `content` and `embedding` that differ for `ids`, in place, so a moved chunk keeps its rowid and vector.'
    from apswutils.db import jsonify_if_needed as _j
    cols = [c for c in dict.fromkeys(k for i in ids for k in rows[i]) if c in self.columns_dict and c not in ('id','content','embedding')]
    if not cols: return
    old = {r['id']: r for r in self(select=','.join(f'[{c}]' for c in ['id',*cols]), where=sql_in('id', ids))}
    upd = [dict(id=i, **{c: rows[i].get(c) for c in cols}) for i in ids if any(_j(rows[i].get(c)) != old.get(i, {}).get(c) for c in cols)]
    if upd: upsert_all(self, upd, 'id', chunk)

@patch
def sync(self:Table,            # store table (hash-id; ANN mirrored if registered)
         content,               # iterable of chunk dicts with 'content'
         key_col:str=None,      # scope existing rows by this column's values (e.g. 'path','package'); None = whole table
         emb_fn=None,           # embedder for new/changed chunks
         embed:bool=True,       # embed before upsert
         force:bool=False,      # treat all content as new (skip diff)
         parallel:bool=False,   # deprecated and ignored
         chunk:int=1_000):      # rows per write transaction
    'Replace store content and update its HNSW index. Attempt a WAL checkpoint after the write. Return change counts.'
    with db_lock(self.db):
        content = L(content).filter(lambda d: d.get('content') and d['content'].strip())
        cont_hash = {content_id(d['content']): d for d in content}
        if force: ex = set()
        elif key_col:
            vals = {v for d in content if (v:=d.get(key_col)) is not None}
            kw = dict(select='id', where=sql_in(key_col, vals))
            ex = set(L(self(**kw)).itemgot('id')) if vals else set()
        else: ex = set(L(self(select='id')).itemgot('id'))
        stale  = ex - cont_hash.keys()
        to_add = filter_keys(cont_hash, not_(in_(ex)))
        m  = self.db._ann_meta(self.name)
        dt = NP_DTYPE.get(m['dtype'], np.float16) if m else np.float16
        rm_rowids = L(self(select=rowid_sel(), where=sql_in('id', stale))).itemgot('rowid') if (m and stale) else L()
        if stale: self.delete_where(where=sql_in('id', stale))
        if to_add: process_content(self, list(to_add.values()), embed=embed, emb_fn=emb_fn, chunk=chunk)
        if same := [i for i in cont_hash if i in ex]: self._refresh(same, cont_hash, chunk)
        if m: self._sync_index(list(to_add), list(rm_rowids), dt)
        _checkpoint(self.db)
        return dict(changed=len(to_add), same=len(ex)-len(stale), removed=len(stale))

@patch
def rebuild_index(self:Table, dtype=None):
    'Rebuild the HNSW index from the embeddings stored in the table and return the number of vectors in it.'
    with db_lock(self.db):
        m = self.db._ann_meta(self.name)
        assert m, f'{self.name!r} is not an ANN store'
        dt = dtype or NP_DTYPE.get(m['dtype'], np.float16)
        keys, vecs = self._vecs(dt)
        self.db.ann_indices.pop(self.name, None)
        if not len(keys):
            if not m['ndim']: return 0                                   # never had vectors; nothing to clear
            self.db.get_index(self.name, load=False).reset()  # empty index, ignore the stale sidecar
            self.db._save_index(self.name)                               # overwrite sidecar to reflect empty table
            return 0
        if m['ndim'] != (nd := vecs.shape[1]): self.db.t.usearch_indices.update(dict(name=self.name, ndim=nd))
        idx = self.db.get_index(self.name, load=False); idx.reset()
        idx.add(keys, vecs)
        self.db._save_index(self.name)
        return idx.size

